#include "CreativeEffects.h"
#include <cmath>
#include <type_traits>
namespace pulse {
using namespace juce;
const std::array<CreativeSpec,4>& echoSpecs(){static const std::array<CreativeSpec,4> s{{{"repeats","Repeat count",1,16,4,"",false,true},{"interval","Repeat interval",20,1000,250," ms",true},{"fade","Fade per repeat",0,1,.4,""},{"mix","Wet mix",0,1,.3,""}}};return s;}
const std::array<CreativeSpec,8>& distortionSpecs(){static const std::array<CreativeSpec,8> s{{{"drive","Drive",0,48,18," dB"},{"lowCut","Low cut",20,1000,80," Hz",true},{"tone","Tone",800,12000,6500," Hz",true},{"presence","Presence",-12,12,0," dB"},{"asymmetry","Asymmetry",0,1,0,""},{"cabinet","Cabinet colour",0,1,.5,""},{"mix","Wet mix",0,1,1,""},{"output","Output",-24,6,-6," dB"}}};return s;}
double creativeNormal(const CreativeSpec& s,double v){return jlimit(0.,1.,s.logarithmic?std::log(v/s.low)/std::log(s.high/s.low):(v-s.low)/(s.high-s.low));}
double creativeValue(const CreativeSpec& s,double v){v=jlimit(0.,1.,v);double result=s.logarithmic?s.low*std::pow(s.high/s.low,v):s.low+(s.high-s.low)*v;return s.integer?std::round(result):result;}
double echoValue(const EchoSettings& s,int i){switch(i){case 0:return s.repeats;case 1:return s.interval;case 2:return s.fade;default:return s.mix;}}
double distortionValue(const DistortionSettings& s,int i){switch(i){case 0:return s.drive;case 1:return s.lowCut;case 2:return s.tone;case 3:return s.presence;case 4:return s.asymmetry;case 5:return s.cabinet;case 6:return s.mix;default:return s.output;}}
static Result checkValue(const CreativeSpec& s,double v){return std::isfinite(v)&&v>=s.low&&v<=s.high&&(!s.integer||v==std::floor(v))?Result::ok():Result::fail(String("Invalid ")+s.name+" ("+String(s.low)+" to "+String(s.high)+s.unit+").");}
Result setEchoValue(EchoSettings& s,int i,double v){if(i<0||i>=4)return Result::fail("Unknown Delay parameter.");auto r=checkValue(echoSpecs()[(size_t)i],v);if(r.failed())return r;switch(i){case 0:s.repeats=(int)v;break;case 1:s.interval=(float)v;break;case 2:s.fade=(float)v;break;case 3:s.mix=(float)v;break;}return Result::ok();}
Result setDistortionValue(DistortionSettings& s,int i,double v){if(i<0||i>=8)return Result::fail("Unknown Distortion parameter.");auto r=checkValue(distortionSpecs()[(size_t)i],v);if(r.failed())return r;switch(i){case 0:s.drive=(float)v;break;case 1:s.lowCut=(float)v;break;case 2:s.tone=(float)v;break;case 3:s.presence=(float)v;break;case 4:s.asymmetry=(float)v;break;case 5:s.cabinet=(float)v;break;case 6:s.mix=(float)v;break;case 7:s.output=(float)v;break;}return Result::ok();}
Result validateEcho(const EchoSettings& s){for(int i=0;i<4;++i){auto r=checkValue(echoSpecs()[(size_t)i],echoValue(s,i));if(r.failed())return r;}return Result::ok();}
Result validateDistortion(const DistortionSettings& s){if(s.mode<0||s.mode>2)return Result::fail("Invalid Distortion clipping style.");for(int i=0;i<8;++i){auto r=checkValue(distortionSpecs()[(size_t)i],distortionValue(s,i));if(r.failed())return r;}return Result::ok();}
var echoToJson(const EchoSettings& s){auto* o=new DynamicObject();o->setProperty("enabled",s.enabled);for(int i=0;i<4;++i){auto key=echoSpecs()[(size_t)i].key;if(i==0)o->setProperty(key,s.repeats);else o->setProperty(key,echoValue(s,i));}return var(o);}
var distortionToJson(const DistortionSettings& s){auto* o=new DynamicObject();o->setProperty("enabled",s.enabled);o->setProperty("mode",s.mode);for(int i=0;i<8;++i)o->setProperty(distortionSpecs()[(size_t)i].key,distortionValue(s,i));return var(o);}
template<class T,size_t N> static Result readSettings(const var& v,T& out,const std::array<CreativeSpec,N>& specs){if(!v.isObject()||!v["enabled"].isBool())return Result::fail("Invalid effect object or bypass state.");T next;next.enabled=(bool)v["enabled"];for(const auto& p:v.getDynamicObject()->getProperties()){bool known=p.name==Identifier("enabled");if constexpr(std::is_same_v<T,DistortionSettings>)known|=p.name==Identifier("mode");for(const auto& s:specs)known|=p.name==Identifier(s.key);if(!known)return Result::fail("Unknown effect setting.");}for(size_t i=0;i<N;++i){auto x=v[specs[i].key];if(!(x.isInt()||x.isInt64()||x.isDouble()))return Result::fail("Missing or nonnumeric effect setting.");auto r=checkValue(specs[i],(double)x);if(r.failed())return r;if constexpr(std::is_same_v<T,EchoSettings>)setEchoValue(next,(int)i,(double)x);else setDistortionValue(next,(int)i,(double)x);}if constexpr(std::is_same_v<T,DistortionSettings>){auto mode=v["mode"];if(!(mode.isInt()||mode.isInt64())||(int64)mode<0||(int64)mode>2)return Result::fail("Invalid clipping style.");next.mode=(int)mode;}out=next;return Result::ok();}
Result echoFromJson(const var& v,EchoSettings& s){return readSettings(v,s,echoSpecs());}
Result distortionFromJson(const var& v,DistortionSettings& s){return readSettings(v,s,distortionSpecs());}
void FiniteEcho::prepare(double sr){rate=jlimit(8000.,192000.,sr);capacity=(size_t)std::ceil(rate)*16+2;for(auto& h:history)h.reset(new float[capacity]);smoothing=1-std::exp(-1/(rate*.015));reset();setSettings(settings);}
void FiniteEcho::reset() noexcept{write=filled=0;mix=settings.mix;decay=1-settings.fade;interval=targetInterval;}
void FiniteEcho::setSettings(const EchoSettings& s,bool preserveHistory){bool clear=(!preserveHistory&&(s.interval!=settings.interval||s.repeats!=settings.repeats))||s.enabled!=settings.enabled;settings=s;targetInterval=jmax(1.,std::round(rate*s.interval*.001));smoothTime=preserveHistory;if(clear)reset();if(!smoothTime)interval=targetInterval;}
void FiniteEcho::process(float& l,float& r) noexcept{if(!settings.enabled||!capacity)return;if(smoothTime)interval+=(targetInterval-interval)*smoothing;mix+=(settings.mix-mix)*(float)smoothing;decay+=(1-settings.fade-decay)*(float)smoothing;float wetL=0,wetR=0,gain=1;for(int tap=1;tap<=settings.repeats;++tap){double delay=interval*tap;size_t age=(size_t)delay;float fraction=(float)(delay-age);if(age+(fraction>0?1:0)<=filled&&age+1<capacity){size_t at=(write+capacity-age)%capacity,older=(at+capacity-1)%capacity;for(int ch=0;ch<2;++ch){float value=history[(size_t)ch][at];if(fraction>0)value+=fraction*(history[(size_t)ch][older]-value);(ch==0?wetL:wetR)+=value*gain;}}gain*=decay;}history[0][write]=l;history[1][write]=r;write=(write+1)%capacity;filled=jmin(filled+1,capacity-1);l=l*(1-mix)+wetL*mix;r=r*(1-mix)+wetR*mix;}
void GuitarDistortion::prepare(double sr){rate=jlimit(8000.,192000.,sr);smoothing=1-std::exp(-1/(rate*.015));reset();}
void GuitarDistortion::reset() noexcept{state={};for(int i=0;i<8;++i)smooth[(size_t)i]=distortionValue(settings,i);}
void GuitarDistortion::setSettings(const DistortionSettings& s){if(s.enabled!=settings.enabled||s.mode!=settings.mode){settings=s;reset();}else settings=s;}
void GuitarDistortion::process(float& l,float& r) noexcept{
    if(!settings.enabled)return;
    for(int i=0;i<8;++i)smooth[(size_t)i]+=(distortionValue(settings,i)-smooth[(size_t)i])*smoothing;
    double drive=std::pow(10.,smooth[0]/20),presence=std::pow(10.,smooth[3]/20)-1,bias=smooth[4]*.4,output=std::pow(10.,smooth[7]/20),sr=rate*4;
    auto pole=[&](double hz){return 1-std::exp(-2*MathConstants<double>::pi*jmin(hz,rate*.45)/sr);};double low=pole(smooth[1]),tone=pole(smooth[2]),air=pole(1800),cab1=pole(4200),cab2=pole(3200),cabLow=pole(80),dc=pole(8),anti=pole(rate*.44);
    auto shape=[&](double x){if(settings.mode==1)return jlimit(-1.,1.,x);if(settings.mode==2)return std::tanh(x*2.5)*(x>=0?1.:.65);return std::tanh(x);};
    float* channels[]={&l,&r};for(int c=0;c<2;++c){auto& s=state[(size_t)c];double dry=*channels[c],sum=0;for(int sub=1;sub<=4;++sub){double x=s.previous+(dry-s.previous)*sub*.25;s.low+=(x-s.low)*low;x-=s.low;x=shape(x*drive+bias)-shape(bias);s.dc+=(x-s.dc)*dc;x-=s.dc;s.tone+=(x-s.tone)*tone;s.air+=(s.tone-s.air)*air;x=s.tone+(s.tone-s.air)*presence;s.cabLow+=(x-s.cabLow)*cabLow;s.cab1+=(x-s.cabLow-s.cab1)*cab1;s.cab2+=(s.cab1-s.cab2)*cab2;x=x*(1-smooth[5])+s.cab2*smooth[5];s.anti1+=(x-s.anti1)*anti;s.anti2+=(s.anti1-s.anti2)*anti;sum+=s.anti2;}s.previous=dry;double wet=sum*.25*output;*channels[c]=(float)(dry*(1-smooth[6])+wet*smooth[6]);}
}
}
